function saveMatAdminV92(){
  const cat=(adminMatCat.value||'EXTRA').toUpperCase();
  const code=(adminMatCode.value||'').toUpperCase();
  if(adminEditMatId){
    const m=state.materials.find(x=>x.id===adminEditMatId);
    if(m){Object.assign(m,{cat,code,name:adminMatName.value,price:adminMatPrice.value,status:adminMatStatus.value});}
  } else {
    const existing=state.materials.find(m=>(m.cat||'').toUpperCase()===cat && (m.code||'').toUpperCase()===code);
    if(existing){Object.assign(existing,{cat,code,name:adminMatName.value,price:adminMatPrice.value,status:adminMatStatus.value}); adminEditMatId=existing.id;}
    else state.materials.push({id:id(),cat,code,name:adminMatName.value,price:adminMatPrice.value,status:adminMatStatus.value});
  }
  save(); adminRender(); renderCats?.(); alert('Materiaal opgeslagen');
}
