  function allCats(){ var cats=(S().materials||[]).map(function(m){return catKey(m.cat||m.rubriek||m.category);}).filter(Boolean); cats=Array.from(new Set(cats)); cats.sort(); return cats.length?cats:["TW","TO","KW","EXTRA"]; }
