    if(!target) target=list.find(function(m){ return tokenOf(m)===token; });
    if(!target){ target={id:'mat_'+Date.now()+'_'+Math.random().toString(36).slice(2,7)}; list.unshift(target); }
    var ids={}; ids[String(target.id)]=1;
