    var m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/); if(m) return mk(+m[1],+m[2],+m[3]);
    m=s.match(/^(\d{1,2})-(\d{1,2})-(\d{4})$/); if(m) return mk(+m[3],+m[2],+m[1]);
